class SemanticMd < Formula
  desc "Convert HTML to clean, semantic Markdown optimized for LLMs"
  homepage "https://github.com/thorstenpfister/semantic-markdown"
  version "1.0.3"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.3/semantic-md-v1.0.3-darwin-arm64.tar.gz"
      sha256 "e9186c2a042f3c1de51874873367d5a9a125aa526917546117b3759c80302f3e"
    end
    if Hardware::CPU.intel?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.3/semantic-md-v1.0.3-darwin-amd64.tar.gz"
      sha256 "2ee7fc6f1c00c70aaad47427d9e1e0c4eed760e164f862e3a5e26efd26533f00"
    end
  end

  on_linux do
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.3/semantic-md-v1.0.3-linux-arm64.tar.gz"
      sha256 "47f957c9b59b4094a4b7c20b97826e2b6da374bd6602c49f67cbf1b4c41e6aff"
    end
    if Hardware::CPU.intel?
      url "https://github.com/thorstenpfister/semantic-markdown/releases/download/v1.0.3/semantic-md-v1.0.3-linux-amd64.tar.gz"
      sha256 "b8f8b44bf4027fff00e825b0efdd36f78b9e1c07752dab702254554a759aedec"
    end
  end

  def install
    bin.install "semantic-md-darwin-arm64" => "semantic-md" if OS.mac? && Hardware::CPU.arm?
    bin.install "semantic-md-darwin-amd64" => "semantic-md" if OS.mac? && Hardware::CPU.intel?
    bin.install "semantic-md-linux-arm64" => "semantic-md" if OS.linux? && Hardware::CPU.arm?
    bin.install "semantic-md-linux-amd64" => "semantic-md" if OS.linux? && Hardware::CPU.intel?
  end

  test do
    assert_match "semantic-md version", shell_output("#{bin}/semantic-md version")
    html = "<h1>Test</h1><p>Content</p>"
    output = pipe_output("#{bin}/semantic-md convert", html)
    assert_match "# Test", output
  end
